using UnityEngine;

namespace G3.Unity
{
    /// <summary>
    /// Settings of the original Gothic 3 trees (SpeedTreeRT meshes generated by Tools/SptBake, imported by
    /// G3SpeedTreeImporter). Asset: <see cref="AssetPath"/>. The world import places these trees instead of the
    /// replacement catalog when <see cref="useOriginalTrees"/> is on and the tree could be generated.
    /// </summary>
    [CreateAssetMenu(menuName = "G3/SpeedTree Settings", fileName = "SpeedTreeSettings")]
    public sealed class G3SpeedTreeSettings : ScriptableObject
    {
        public const string AssetPath = "Assets/G3/Trees/SpeedTreeSettings.asset";

        [Tooltip("World import: original trees (generated from the installed game) instead of the replacement catalog.")]
        public bool useOriginalTrees = true;

        [Header("Generator (Tools/SptBake)")]
        [Tooltip("Folder of the generated .g3tree files, relative to the project (git-ignored, regenerated on demand).")]
        public string bakeDirectory = "Temp/SptBake";
        [Tooltip("SptBake executable, relative to the project. Built with 'dotnet build -c Release' in Tools/SptBake.")]
        public string bakerExecutable = "Tools/SptBake/bin/Release/net8.0/win-x86/SptBake.exe";

        [Header("LOD (engine: discrete levels between LodNear and LodFar × tree height)")]
        [Tooltip("Multiplier on the engine LOD distances.")]
        public float lodDistanceScale = 1f;
        [Tooltip("Earliest switch away from the full-detail level (m). The engine values are tiny for bushes.")]
        public float minFirstTransition = 25f;
        [Tooltip("Minimum distance between two levels (m).")]
        public float minLodStep = 10f;
        [Tooltip("At most this many geometry levels (the engine has up to 6 per part).")]
        [Range(1, 6)] public int maxGeometryLevels = 4;
        [Tooltip("Far LOD: the original 360° billboard. Off = cull after the last geometry level.")]
        public bool billboards = true;
        [Tooltip("Earliest billboard distance (m); the engine's LodFar is used when larger.")]
        public float minBillboardDistance = 120f;
        [Tooltip("Screen height below which the tree is culled (LODGroup).")]
        [Range(0.0005f, 0.05f)] public float cullScreenHeight = 0.003f;
        [Tooltip("Field of view the LOD distances are converted with (LODGroup works in screen heights).")]
        public float referenceFieldOfView = 60f;
        [Tooltip("LOD cross-fade: dithered over a distance band (never time-animated, which the GPU Resident Drawer does not support).")]
        public bool crossFade = true;
        [Tooltip("Fraction of each LOD's screen-height band over which it dithers into the next (LODGroup fadeTransitionWidth).")]
        [Range(0, 1)] public float crossFadeWidth = 0.15f;

        [Header("Materials")]
        [Range(0, 1)] public float alphaCutoff = 84f / 255f;
        [Range(0, 1)] public float barkSmoothness = 0.08f;
        [Range(0, 1)] public float leafSmoothness = 0.12f;
        [Tooltip("Multiplier on the G3Wind bend for the SpeedTree wind weights.")]
        [Range(0, 20)] public float windScale = 6f;
        [Range(0, 0.5f)] public float leafRock = 0.06f;
        [Range(0, 10)] public float leafRockSpeed = 2.2f;
    }
}
